 68	  for (const [id, m] of runner.models) planModels.set(id, { gates: m.gates.map((g) => ({ id: g.id, criteria: g.criteria, capture: g.capture })), file: m.file });
 69	  // Route stray stderr (SDK warnings, child noise) into diagnostics instead of smearing the cockpit.
 70	  const origErr = process.stderr.write.bind(process.stderr);
 71	  process.stderr.write = ((chunk: string | Uint8Array) => { const text = String(chunk).trim(); if (text) runner.emit("event", { t: Date.now(), kind: "log", level: /warn/i.test(text) ? "warn" : "error", source: "stderr", message: text.split("\n")[0].slice(0, 300) }); return true; }) as typeof process.stderr.write;
 72	  const ink = render(React.createElement(App, { runner, animate, initialLevel: config.logLevel, planModels }), { exitOnCtrlC: true });
 73	  process.on("exit", () => { process.stderr.write = origErr; });
