/**
 * PlanSession — drives one Claude Agent SDK query() per plan (or prompt),
 * in streaming-input mode so the TUI can inject instructions / interrupt,
 * and turns the SDK message stream + hooks into RunEvents.
 */
import { query, type Options, type SDKMessage, type SDKUserMessage, type HookCallback, type CanUseTool, type PermissionMode, type Query } from "@anthropic-ai/claude-agent-sdk";
import { existsSync, statSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { EventEmitter } from "node:events";
import type { RunEvent, Verdict, TokenUsage } from "./events.js";
import { now } from "./events.js";
import { evaluateRails, type Rail } from "./rails.js";
import { parseVerdictLines, LineBuffer } from "../plan/verdict.js";
import type { PlanModel, PlanGate } from "../plan/parser.js";

export type ApprovalMode = "auto" | "gates" | "all";

export interface SessionOpts {
  planId: string; // "prompt" for prompt mode
  plan?: PlanModel;
  prompt: string;
  cwd: string;
  env: Record<string, string>;
  model: string;
  maxTurns: number;
