}

export interface ApprovalRequest { requestId: string; tool: string; input: unknown; resolve: (allow: boolean, note?: string) => void; }
export interface GateApproval { gateId: string; verdict: "pass" | "fail"; reason?: string; resolve: (accept: boolean) => void; }

/** Emits: event(RunEvent), approval(ApprovalRequest), gateApproval(GateApproval) */
export class PlanSession extends EventEmitter {
  private q: Query | null = null;
  private inbox: SDKUserMessage[] = [];
  private wake: (() => void) | null = null;
  private closed = false;
  private toolStart = new Map<string, { name: string; t: number; out: string }>();
  private lines = new Map<string, LineBuffer>(); // per parent id
  private paused = false;
  private pausedWaiters: Array<() => void> = [];
  gateState = new Map<string, Verdict>();
  planVerdict: "pass" | "fail" | null = null;
  sessionId: string | null = null;

  constructor(readonly opts: SessionOpts) {
    super();
    for (const g of opts.plan?.gates ?? []) this.gateState.set(g.id, "pending");
  }

  private emitEv(ev: RunEvent) { this.emit("event", ev); }
  private log(level: "debug" | "info" | "warn" | "error", source: string, message: string) { this.emitEv({ t: now(), kind: "log", level, source, message }); }

