  1	/**
  2	 * Redactor — replaces secrets with a stable, non-recoverable placeholder.
  3	 *
  4	 * Run artifacts (events.jsonl, tools/*.txt, gates.json, cost.json) are kept
  5	 * forever and are meant to be shared with auditors, so anything that looks like
  6	 * a credential must never reach disk. A secret becomes `[redacted:<8 hex>]`
  7	 * where the hex is the sha256 prefix of the secret: two different secrets stay
  8	 * distinguishable across a run, but neither is recoverable from the artifact.
  9	 *
 10	 * Throughput matters — this sits on the hot write path of every run — so all
 11	 * literals, built-ins and user patterns are compiled into ONE global RegExp and
 12	 * each string is scanned in a single pass, with secret -> placeholder memoised.
 13	 */
 14	import { createHash } from "node:crypto";
 15	
 16	export interface RedactPattern {
 17	  /** stable id, used in docs/tests to name the shape this pattern covers */
 18	  id: string;
 19	  /** regex source; an optional capture group marks the secret portion of the match */
 20	  source: string;
 21	}
 22	
 23	export interface RedactorOptions {
 24	  /** exact strings always redacted (e.g. the resolved auth token) */
 25	  literals?: string[];
 26	  /** extra user regex sources from config.redact */
 27	  patterns?: string[];
 28	  /** include BUILTIN_REDACT_PATTERNS (default: true) */
 29	  builtins?: boolean;
 30	}
 31	
 32	/** Escape a literal so it can be embedded in a RegExp source. */
 33	function escapeRegExp(s: string): string {
 34	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
 35	}
 36	
 37	/**
 38	 * Case-insensitive source for a literal word. JS has no inline (?i), and the
 39	 * combined regex must stay case-SENSITIVE (so `AKIA…` does not match lowercase
 40	 * prose), so per-word insensitivity is spelled out as character classes.
 41	 */
 42	function anyCase(word: string): string {
 43	  return word.replace(/[A-Za-z]/g, (c) => `[${c.toUpperCase()}${c.toLowerCase()}]`);
 44	}
 45	
 46	/**
 47	 * Names that make a `NAME=value` assignment secret-bearing. The keyword must
 48	 * start the name, follow a `_`, or be CamelCase — so `API_KEY`, `key`, `apiKey`
 49	 * match while `monkey`, `PATH` and `NODE_ENV` do not.
 50	 */
 51	const SECRET_NAME_KEYWORD = "(?:TOKEN|SECRET|PASSWORD|PASSWD|KEY|token|secret|password|passwd|key)";
 52	/** CamelCase keyword — the capital is what separates `apiKey` from `monkey`. */
 53	const SECRET_NAME_KEYWORD_CAMEL = "(?:Token|Secret|Password|Passwd|Key)";
 54	/** `MY_`, `DB_`, `aws_iam_` … each segment ends in `_` and cannot contain one, so there is no ambiguity to backtrack over. */
 55	const SECRET_NAME =
 56	  `(?:[A-Za-z0-9.-]+_)*(?:${SECRET_NAME_KEYWORD}|[A-Za-z0-9]*${SECRET_NAME_KEYWORD_CAMEL})[A-Za-z0-9_.-]*`;
 57	/** double-quoted | single-quoted | bare; a bare value stops at whitespace, a quote or a shell/JSON terminator. */
 58	const ASSIGNED_VALUE = "(?:\"([^\"\\n]*)\"|'([^'\\n]*)'|([^\\s\"'`,;)}]+))";
 59	
 60	/**
 61	 * Built-in shapes, tried in this order when two match at the same offset.
 62	 * Where a prefix must stay readable (`Authorization: `, `API_KEY=`) only the
 63	 * capture group is replaced, so the artifact still shows what was there.
 64	 */
 65	export const BUILTIN_REDACT_PATTERNS: RedactPattern[] = [
 66	  {
 67	    // whole PEM block, first so an inner line is never matched on its own
 68	    id: "pem-private-key",
 69	    source: "-----BEGIN [A-Z ]*PRIVATE KEY-----[\\s\\S]*?-----END [A-Z ]*PRIVATE KEY-----",
 70	  },
 71	  {
 72	    // Authorization: Bearer <cred> / "authorization": "<cred>" / Authorization=<cred>
 73	    id: "authorization-header",
 74	    source:
 75	      `["']?${anyCase("authorization")}["']?\\s*[:=]\\s*["']?` +
 76	      `(?:(?:${anyCase("bearer")}|${anyCase("basic")}|${anyCase("token")})\\s+)?([^\\s"',;}]+)`,
 77	  },
 78	  {
 79	    // a bare `Bearer <token>` with no header name; long enough not to hit prose
 80	    id: "bearer-token",
 81	    source: `\\b${anyCase("bearer")}\\s+([A-Za-z0-9._~+/=-]{16,})`,
 82	  },
 83	  {
 84	    id: "aws-secret-access-key",
 85	    source: `["']?${anyCase("aws_secret_access_key")}["']?\\s*[:=]\\s*["']?([A-Za-z0-9/+=]{40})`,
 86	  },
 87	  {
 88	    id: "aws-access-key-id",
 89	    source: "\\b(?:AKIA|ASIA)[0-9A-Z]{16}\\b",
 90	  },
 91	  {
 92	    // sk-…, sk-ant-…, and friends
 93	    id: "openai-style-key",
 94	    source: "\\bsk-[A-Za-z0-9_-]{16,}",
 95	  },
 96	  {
 97	    // NAME=value / NAME = value / export NAME=value / "name": "value"
 98	    id: "env-assignment",
 99	    source: `(?<![A-Za-z0-9_])(?:${anyCase("export")}\\s+)?["']?${SECRET_NAME}["']?\\s*[:=]\\s*${ASSIGNED_VALUE}`,
100	  },
101	];
102	
103	/** `[redacted:<first 8 hex of sha256(secret)>]` — stable within and across runs. */
104	export function placeholder(secret: string): string {
105	  return `[redacted:${createHash("sha256").update(secret).digest("hex").slice(0, 8)}]`;
106	}
107	
108	export class Redactor {
109	  /** null when there is nothing to match — redact() then returns its input untouched. */
110	  private readonly re: RegExp | null;
111	  private readonly cache = new Map<string, string>();
112	
113	  constructor(opts: RedactorOptions = {}) {
114	    const parts: string[] = [];
115	
116	    // literals first: an exact known secret wins over any pattern at the same offset.
117	    // longest first so a token that contains another token is redacted whole.
118	    const literals = [...new Set((opts.literals ?? []).filter((l) => typeof l === "string" && l.trim() !== ""))].sort(
119	      (a, b) => b.length - a.length,
120	    );
121	    for (const lit of literals) parts.push(`(?:${escapeRegExp(lit)})`);
122	
123	    if (opts.builtins !== false) for (const p of BUILTIN_REDACT_PATTERNS) parts.push(`(?:${p.source})`);
124	
125	    for (const src of opts.patterns ?? []) {
126	      if (typeof src !== "string" || src.trim() === "") continue;
127	      try {
128	        new RegExp(src);
129	      } catch (e) {
130	        throw new Error(`redact: invalid regular expression /${src}/ — ${(e as Error).message}`);
131	      }
132	      // wrapped so a top-level `|` stays scoped; a user capture group marks the
133	      // secret portion (backreferences are not supported — groups are renumbered).
134	      parts.push(`(?:${src})`);
135	    }
136	
137	    this.re = parts.length ? new RegExp(parts.join("|"), "gd") : null;
138	  }
139	
140	  /** Replace every match in `text`. Returns the same string when nothing matched. */
141	  redact(text: string): string {
142	    const re = this.re;
143	    if (re === null || text.length === 0) return text;
144	    re.lastIndex = 0;
145	    let out = "";
146	    let last = 0;
147	    let m: RegExpExecArray | null;
148	    while ((m = re.exec(text)) !== null) {
149	      if (m[0].length === 0) {
150	        re.lastIndex++; // zero-length match: never allowed to spin
151	        continue;
152	      }
153	      const [start, end] = this.secretSpan(m);
154	      const secret = text.slice(start, end);
155	      if (secret.trim() === "") continue; // e.g. API_KEY="" — nothing to hide
156	      out += text.slice(last, start) + this.placeholderFor(secret);
157	      last = end;
158	    }
159	    if (last === 0) return text; // fast path: allocate nothing when clean
160	    return out + text.slice(last);
161	  }
162	
163	  /** The span to replace: the first participating capture group, else the whole match. */
164	  private secretSpan(m: RegExpExecArray): [number, number] {
165	    for (let i = 1; i < m.length; i++) {
166	      const g = m[i];
167	      if (g === undefined) continue;
168	      const span = m.indices?.[i];
169	      if (span) return [span[0], span[1]];
170	      // no `d` flag support: the secret is the tail of the match in every built-in
171	      const at = m[0].lastIndexOf(g);
172	      if (at >= 0) return [m.index + at, m.index + at + g.length];
173	      break;
174	    }
175	    return [m.index, m.index + m[0].length];
176	  }
177	
178	  private placeholderFor(secret: string): string {
179	    let p = this.cache.get(secret);
180	    if (p === undefined) {
181	      p = placeholder(secret);
182	      this.cache.set(secret, p);
183	    }
184	    return p;
185	  }
186	}
187

 1	/**
 2	 * RunEvent — the single vocabulary Vigil uses for everything it observes.
 3	 * Every event is appended to runs/<id>/events.jsonl and reduced into UI state.
 4	 */
 5	
