import { describe, it, expect } from "vitest";
import { mkdtempSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { renderValidation, updateRoadmapStatus } from "../src/plan/reports.js";
import { parsePlan } from "../src/plan/parser.js";
import { RunStore } from "../src/engine/store.js";

const FIX = resolve(__dirname, "fixtures/omp-live-deploy");

describe("reports", () => {
  it("renders a PASS validation report from gate records", () => {
    const f = resolve(FIX, "phases/01-build-stage/01-02-PLAN.md");
    const p = parsePlan(readFileSync(f, "utf8"), f);
    const now = Date.now();
    const gates = p.gates.map((g) => ({ planId: p.id, gateId: g.id, verdict: "pass" as const, evidence: [{ path: "vg3-card.png", present: true, bytes: 100 }], updatedAt: now }));
    const md = renderValidation([p], gates, { phase: "01-build-stage", runId: "r1", evidenceDir: "phases/01-build-stage/evidence" });
    expect(md).toContain("Verdict: PASS");
    expect(md).toContain("| VG-PHASE-01 | PASS |");
    expect(md).toContain("| Integration | PASS |");
    expect(md).toContain("Failures\nNone");
  });
  it("updates the ROADMAP status row for a phase", () => {
    const dir = mkdtempSync(join(tmpdir(), "vigil-"));
    const rp = join(dir, "ROADMAP.md");
    writeFileSync(rp, readFileSync(resolve(FIX, "ROADMAP.md"), "utf8"));
    expect(updateRoadmapStatus(rp, "01", "✓ Validated", "VG-PHASE-01 PASS", "runs/r1")).toBe(true);
    const md = readFileSync(rp, "utf8");
    expect(md).toMatch(/^\| 01 \| ✓ Validated \| VG-PHASE-01 PASS \| runs\/r1 \|$/m);
    expect(md).toMatch(/^\| 02 \| ○ Not started/m);
  });
  it("RunStore persists events, tool transcripts and gates", () => {
    const dir = mkdtempSync(join(tmpdir(), "vigil-"));
    const s = new RunStore(dir, RunStore.newRunId("test"));
    const t = Date.now();
    s.append({ t, kind: "tool.start", planId: "p", toolUseId: "tu1", name: "Bash", input: { command: "echo hi" }, parentToolUseId: null });
    s.append({ t, kind: "tool.output", planId: "p", toolUseId: "tu1", chunk: "hi\n" });
    s.append({ t, kind: "tool.end", planId: "p", toolUseId: "tu1", ok: true, durationMs: 5, output: "hi\n" });
    s.append({ t, kind: "gate.update", planId: "p", gateId: "VG-1", verdict: "pass", evidence: [] });
    const evs = RunStore.readEvents(s.dir);
    expect(evs).toHaveLength(4);
    const tf = readFileSync(join(s.dir, "tools", "0001-Bash.txt"), "utf8");
    expect(tf).toContain("echo hi");
    expect(tf.match(/^hi$/gm)).toHaveLength(1); // streamed output not duplicated at end
    expect(JSON.parse(readFileSync(join(s.dir, "gates.json"), "utf8"))["p/VG-1"].verdict).toBe("pass");
  });
});
