  2	 * Redactor — replaces secrets with a stable, non-recoverable placeholder.
  3	 *
  4	 * Run artifacts (events.jsonl, tools/*.txt, gates.json, cost.json) are kept
  5	 * forever and are meant to be shared with auditors, so anything that looks like
  6	 * a credential must never reach disk. A secret becomes `[redacted:<8 hex>]`
  7	 * where the hex is the sha256 prefix of the secret: two different secrets stay
  8	 * distinguishable across a run, but neither is recoverable from the artifact.
  9	 *
 10	 * Throughput matters — this sits on the hot write path of every run — so all
 11	 * literals, built-ins and user patterns are compiled into ONE global RegExp and
 12	 * each string is scanned in a single pass, with secret -> placeholder memoised.
 13	 */
 14	import { createHash } from "node:crypto";
 15	import type { RunEvent } from "./events.js";
 16	
 17	export interface RedactPattern {
 18	  /** stable id, used in docs/tests to name the shape this pattern covers */
 19	  id: string;
 20	  /** regex source; an optional capture group marks the secret portion of the match */
 21	  source: string;
 22	}
 23	
 24	export interface RedactorOptions {
 25	  /** exact strings always redacted (e.g. the resolved auth token) */
 26	  literals?: string[];
 27	  /** extra user regex sources from config.redact */
 28	  patterns?: string[];
 29	  /** include BUILTIN_REDACT_PATTERNS (default: true) */
 30	  builtins?: boolean;
 31	}
