115	/** `[redacted:<first 8 hex of sha256(secret)>]` — stable within and across runs. */
116	export function placeholder(secret: string): string {
117	  return `[redacted:${createHash("sha256").update(secret).digest("hex").slice(0, 8)}]`;
118	}
