  1	/**
  2	 * Redactor — replaces secrets with a stable, non-recoverable placeholder.
  3	 *
  4	 * Run artifacts (events.jsonl, tools/*.txt, gates.json, cost.json) are kept
  5	 * forever and are meant to be shared with auditors, so anything that looks like
  6	 * a credential must never reach disk. A secret becomes `[redacted:<8 hex>]`
  7	 * where the hex is the sha256 prefix of the secret: two different secrets stay
  8	 * distinguishable across a run, but neither is recoverable from the artifact.
  9	 *
 10	 * Throughput matters — this sits on the hot write path of every run — so all
 11	 * literals, built-ins and user patterns are compiled into ONE global RegExp and
 12	 * each string is scanned in a single pass, with secret -> placeholder memoised.
 13	 */
 14	import { createHash } from "node:crypto";
 15	import type { RunEvent } from "./events.js";
 16	
 17	export interface RedactPattern {
 18	  /** stable id, used in docs/tests to name the shape this pattern covers */
 19	  id: string;
 20	  /** regex source; an optional capture group marks the secret portion of the match */
 21	  source: string;
 22	}
 23	
 24	export interface RedactorOptions {
 25	  /** exact strings always redacted (e.g. the resolved auth token) */
 26	  literals?: string[];
 27	  /** extra user regex sources from config.redact */
 28	  patterns?: string[];
 29	  /** include BUILTIN_REDACT_PATTERNS (default: true) */
 30	  builtins?: boolean;
 31	}
 32	
 33	/**
 34	 * Only plain JSON-ish containers are walked. Everything a RunEvent carries is
 35	 * JSON (it is JSON.stringify'd straight to events.jsonl), so an exotic object
 36	 * would not survive serialisation anyway — it is returned untouched rather than
 37	 * silently flattened into a plain object.
 38	 */
 39	function isPlainObject(v: object): boolean {
 40	  const p = Object.getPrototypeOf(v) as unknown;
 41	  return p === Object.prototype || p === null;
 42	}
 43	
 44	/** Escape a literal so it can be embedded in a RegExp source. */
 45	function escapeRegExp(s: string): string {
 46	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
 47	}
 48	
 49	/**
 50	 * Case-insensitive source for a literal word. JS has no inline (?i), and the
 51	 * combined regex must stay case-SENSITIVE (so `AKIA…` does not match lowercase
 52	 * prose), so per-word insensitivity is spelled out as character classes.
 53	 */
 54	function anyCase(word: string): string {
 55	  return word.replace(/[A-Za-z]/g, (c) => `[${c.toUpperCase()}${c.toLowerCase()}]`);
 56	}
 57	
 58	/**
 59	 * Names that make a `NAME=value` assignment secret-bearing. The keyword must
 60	 * start the name, follow a `_`, or be CamelCase — so `API_KEY`, `key`, `apiKey`
 61	 * match while `monkey`, `PATH` and `NODE_ENV` do not.
 62	 */
 63	const SECRET_NAME_KEYWORD = "(?:TOKEN|SECRET|PASSWORD|PASSWD|KEY|token|secret|password|passwd|key)";
 64	/** CamelCase keyword — the capital is what separates `apiKey` from `monkey`. */
 65	const SECRET_NAME_KEYWORD_CAMEL = "(?:Token|Secret|Password|Passwd|Key)";
 66	/** `MY_`, `DB_`, `aws_iam_` … each segment ends in `_` and cannot contain one, so there is no ambiguity to backtrack over. */
 67	const SECRET_NAME =
 68	  `(?:[A-Za-z0-9.-]+_)*(?:${SECRET_NAME_KEYWORD}|[A-Za-z0-9]*${SECRET_NAME_KEYWORD_CAMEL})[A-Za-z0-9_.-]*`;
 69	/** double-quoted | single-quoted | bare; a bare value stops at whitespace, a quote or a shell/JSON terminator. */
 70	const ASSIGNED_VALUE = "(?:\"([^\"\\n]*)\"|'([^'\\n]*)'|([^\\s\"'`,;)}]+))";
 71	
 72	/**
 73	 * Built-in shapes, tried in this order when two match at the same offset.
 74	 * Where a prefix must stay readable (`Authorization: `, `API_KEY=`) only the
 75	 * capture group is replaced, so the artifact still shows what was there.
 76	 */
 77	export const BUILTIN_REDACT_PATTERNS: RedactPattern[] = [
 78	  {
 79	    // whole PEM block, first so an inner line is never matched on its own
 80	    id: "pem-private-key",
 81	    source: "-----BEGIN [A-Z ]*PRIVATE KEY-----[\\s\\S]*?-----END [A-Z ]*PRIVATE KEY-----",
 82	  },
 83	  {
 84	    // Authorization: Bearer <cred> / "authorization": "<cred>" / Authorization=<cred>
 85	    id: "authorization-header",
 86	    source:
 87	      `["']?${anyCase("authorization")}["']?\\s*[:=]\\s*["']?` +
 88	      `(?:(?:${anyCase("bearer")}|${anyCase("basic")}|${anyCase("token")})\\s+)?([^\\s"',;}]+)`,
 89	  },
 90	  {
 91	    // a bare `Bearer <token>` with no header name; long enough not to hit prose
 92	    id: "bearer-token",
 93	    source: `\\b${anyCase("bearer")}\\s+([A-Za-z0-9._~+/=-]{16,})`,
 94	  },
 95	  {
 96	    id: "aws-secret-access-key",
 97	    source: `["']?${anyCase("aws_secret_access_key")}["']?\\s*[:=]\\s*["']?([A-Za-z0-9/+=]{40})`,
 98	  },
 99	  {
100	    id: "aws-access-key-id",
101	    source: "\\b(?:AKIA|ASIA)[0-9A-Z]{16}\\b",
102	  },
103	  {
104	    // sk-…, sk-ant-…, and friends
105	    id: "openai-style-key",
106	    source: "\\bsk-[A-Za-z0-9_-]{16,}",
107	  },
108	  {
109	    // NAME=value / NAME = value / export NAME=value / "name": "value"
110	    id: "env-assignment",
111	    source: `(?<![A-Za-z0-9_])(?:${anyCase("export")}\\s+)?["']?${SECRET_NAME}["']?\\s*[:=]\\s*${ASSIGNED_VALUE}`,
112	  },
113	];
114	
115	/** `[redacted:<first 8 hex of sha256(secret)>]` — stable within and across runs. */
116	export function placeholder(secret: string): string {
117	  return `[redacted:${createHash("sha256").update(secret).digest("hex").slice(0, 8)}]`;
118	}
119	
120	export class Redactor {
121	  /** null when there is nothing to match — redact() then returns its input untouched. */
122	  private readonly re: RegExp | null;
123	  private readonly cache = new Map<string, string>();
124	
125	  constructor(opts: RedactorOptions = {}) {
126	    const parts: string[] = [];
127	
128	    // literals first: an exact known secret wins over any pattern at the same offset.
129	    // longest first so a token that contains another token is redacted whole.
130	    const literals = [...new Set((opts.literals ?? []).filter((l) => typeof l === "string" && l.trim() !== ""))].sort(
131	      (a, b) => b.length - a.length,
132	    );
133	    for (const lit of literals) parts.push(`(?:${escapeRegExp(lit)})`);
134	
135	    if (opts.builtins !== false) for (const p of BUILTIN_REDACT_PATTERNS) parts.push(`(?:${p.source})`);
136	
137	    for (const src of opts.patterns ?? []) {
138	      if (typeof src !== "string" || src.trim() === "") continue;
139	      try {
140	        new RegExp(src);
141	      } catch (e) {
142	        throw new Error(`redact: invalid regular expression /${src}/ — ${(e as Error).message}`);
143	      }
144	      // wrapped so a top-level `|` stays scoped; a user capture group marks the
145	      // secret portion (backreferences are not supported — groups are renumbered).
146	      parts.push(`(?:${src})`);
147	    }
148	
149	    this.re = parts.length ? new RegExp(parts.join("|"), "gd") : null;
150	  }
151	
152	  /** Replace every match in `text`. Returns the same string when nothing matched. */
153	  redact(text: string): string {
154	    const re = this.re;
155	    if (re === null || text.length === 0) return text;
156	    re.lastIndex = 0;
157	    let out = "";
158	    let last = 0;
159	    let m: RegExpExecArray | null;
160	    while ((m = re.exec(text)) !== null) {
161	      if (m[0].length === 0) {
162	        re.lastIndex++; // zero-length match: never allowed to spin
163	        continue;
164	      }
165	      const [start, end] = this.secretSpan(m);
166	      const secret = text.slice(start, end);
167	      if (secret.trim() === "") continue; // e.g. API_KEY="" — nothing to hide
168	      out += text.slice(last, start) + this.placeholderFor(secret);
169	      last = end;
170	    }
171	    if (last === 0) return text; // fast path: allocate nothing when clean
172	    return out + text.slice(last);
173	  }
174	
175	  /**
176	   * Deep-redact a RunEvent: a structurally identical copy with every string —
177	   * and every object KEY, since a parsed .env object can carry a secret as a
178	   * key — passed through redact().
179	   *
180	   * The walk is generic rather than a per-kind switch, so every current variant
181	   * (tool.start.input, tool.output.chunk, tool.end.output, assistant.text/delta,
182	   * log.message, hook.reason, gate.update.reason, control.detail,
183	   * approval.request.input) and every future one is covered automatically.
184	   *
185	   * Never mutates its argument — the UI holds the original — and returns the
186	   * SAME reference when nothing changed, so a clean event allocates nothing.
187	   */
188	  redactEvent<T extends RunEvent>(ev: T): T {
189	    if (this.re === null) return ev;
190	    return this.redactValue(ev) as T;
191	  }
192	
193	  /** Non-mutating copy-on-change walk over any JSON-ish value. */
194	  private redactValue(v: unknown): unknown {
195	    if (typeof v === "string") return this.redact(v);
196	    if (v === null || typeof v !== "object") return v; // number/boolean/undefined/bigint/fn
197	
198	    if (Array.isArray(v)) {
199	      let out: unknown[] | null = null;
200	      for (let i = 0; i < v.length; i++) {
201	        const before: unknown = v[i];
202	        const after = this.redactValue(before);
203	        if (out === null) {
204	          if (after === before) continue;
205	          out = v.slice(0, i); // copy the clean prefix once, on first change
206	        }
207	        out.push(after);
208	      }
209	      return out ?? v;
210	    }
211	
212	    if (!isPlainObject(v)) return v;
213	
214	    const src = v as Record<string, unknown>;
215	    const keys = Object.keys(src);
216	    let out: Record<string, unknown> | null = null;
217	    for (let i = 0; i < keys.length; i++) {
218	      const key = keys[i]!;
219	      const before: unknown = src[key];
220	      const after = this.redactValue(before);
221	      const redKey = this.redact(key); // identity-equal when clean
222	      if (out === null) {
223	        if (after === before && redKey === key) continue;
224	        out = {};
225	        for (let j = 0; j < i; j++) out[keys[j]!] = src[keys[j]!]; // clean prefix, order preserved
226	      }
227	      // two keys can collapse onto one placeholder (same secret twice); last wins,
228	      // which is acceptable — the artifact must be safe, not round-trippable.
229	      out[redKey] = after;
230	    }
231	    return out ?? v;
232	  }
233	
234	  /** The span to replace: the first participating capture group, else the whole match. */
235	  private secretSpan(m: RegExpExecArray): [number, number] {
236	    for (let i = 1; i < m.length; i++) {
237	      const g = m[i];
238	      if (g === undefined) continue;
239	      const span = m.indices?.[i];
240	      if (span) return [span[0], span[1]];
241	      // no `d` flag support: the secret is the tail of the match in every built-in
242	      const at = m[0].lastIndexOf(g);
243	      if (at >= 0) return [m.index + at, m.index + at + g.length];
244	      break;
245	    }
246	    return [m.index, m.index + m[0].length];
247	  }
248	
249	  private placeholderFor(secret: string): string {
250	    let p = this.cache.get(secret);
251	    if (p === undefined) {
252	      p = placeholder(secret);
253	      this.cache.set(secret, p);
254	    }
255	    return p;
256	  }
257	}
258

