/** Env for the SDK child: inherit, unset the listed names, apply overrides, route to baseUrl/token. */
export function buildEnv(cfg: VigilConfig, overrides: Record<string, string> = {}): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) if (v !== undefined && !cfg.unsetEnv.includes(k)) env[k] = v;
  Object.assign(env, cfg.env, overrides);
  if (cfg.baseUrl) env.ANTHROPIC_BASE_URL = cfg.baseUrl;
  const token = cfg.authToken ?? process.env[cfg.authTokenEnv];
  if (token) env.ANTHROPIC_AUTH_TOKEN = token;
  return env;
}

args.new_string:
/**
 * The token the agent will actually authenticate with: explicit config first,
 * else the named env var. Single resolution path so what buildEnv hands to the
 * SDK is exactly what createRedactor hides from artifacts.
 */
export function resolveAuthToken(cfg: VigilConfig): string | undefined {
  return cfg.authToken ?? process.env[cfg.authTokenEnv];
}

/** Env for the SDK child: inherit, unset the listed names, apply overrides, route to baseUrl/token. */
export function buildEnv(cfg: VigilConfig, overrides: Record<string, string> = {}): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) if (v !== undefined && !cfg.unsetEnv.includes(k)) env[k] = v;
  Object.assign(env, cfg.env, overrides);
  if (cfg.baseUrl) env.ANTHROPIC_BASE_URL = cfg.baseUrl;
  const token = resolveAuthToken(cfg);
  if (token) env.ANTHROPIC_AUTH_TOKEN = token;
  return env;
}

/**
 * Shortest credential worth matching literally. Anything below this is either a
 * placeholder or so generic that escaping it into the combined regex would
 * redact ordinary prose (`authToken: ""` must not blank out every artifact).
 */
const MIN_LITERAL_LEN = 8;

/**
 * Build the Redactor for a run: the live credentials by exact match (so they are
 * hidden regardless of pattern coverage), plus the built-in secret shapes and
 * any user `redact` patterns.
 *
 * Lives here rather than in redact.ts so the engine stays free of config imports.
 */
export function createRedactor(cfg: VigilConfig): Redactor {
  // UNSAFE escape hatch: an inert redactor, so call sites need no null checks.
  if (!cfg.redactEnabled) return new Redactor({ builtins: false });
  const literals = [resolveAuthToken(cfg), process.env.ANTHROPIC_AUTH_TOKEN, process.env.ANTHROPIC_API_KEY].filter(
    (t): t is string => typeof t === "string" && t.trim().length >= MIN_LITERAL_LEN,
  );
  return new Redactor({ literals, patterns: cfg.redact, builtins: true });
}

