import { ConfigSchema, createRedactor, resolveAuthToken, buildEnv } from "./config.js";

const ok = (label: string, cond: boolean) => {
  console.log(`${cond ? "PASS" : "FAIL"}  ${label}`);
  if (!cond) process.exitCode = 1;
};

delete process.env.ANTHROPIC_AUTH_TOKEN;
delete process.env.ANTHROPIC_API_KEY;
delete process.env.VIGIL_AUTH_TOKEN;

// resolveAuthToken: explicit config wins, else env var, else undefined
ok("resolveAuthToken undefined when nothing set", resolveAuthToken(ConfigSchema.parse({})) === undefined);
ok("resolveAuthToken from cfg.authToken", resolveAuthToken(ConfigSchema.parse({ authToken: "cfg-token-1234" })) === "cfg-token-1234");
process.env.VIGIL_AUTH_TOKEN = "env-token-1234";
ok("resolveAuthToken from authTokenEnv", resolveAuthToken(ConfigSchema.parse({})) === "env-token-1234");
ok("cfg.authToken beats env", resolveAuthToken(ConfigSchema.parse({ authToken: "cfg-token-1234" })) === "cfg-token-1234");
ok("buildEnv still routes the token", buildEnv(ConfigSchema.parse({})).ANTHROPIC_AUTH_TOKEN === "env-token-1234");

// createRedactor: env-resolved token redacted by exact match
{
  const r = createRedactor(ConfigSchema.parse({}));
  const out = r.redact("used env-token-1234 here");
  ok("env token redacted by literal", !out.includes("env-token-1234") && /\[redacted:[0-9a-f]{8}\]/.test(out));
}
delete process.env.VIGIL_AUTH_TOKEN;

// createRedactor: cfg token redacted by exact match even though no pattern matches it
{
  const cfg = ConfigSchema.parse({ authToken: "plain-literal-token" });
  ok("literal token not matched by a default redactor", !createRedactor(ConfigSchema.parse({})).redact("plain-literal-token").includes("[redacted:"));
  ok("cfg token redacted by literal", !createRedactor(cfg).redact("x plain-literal-token y").includes("plain-literal-token"));
}

// ANTHROPIC_* env literals
process.env.ANTHROPIC_API_KEY = "anthropic-api-key-value";
ok("ANTHROPIC_API_KEY redacted", !createRedactor(ConfigSchema.parse({})).redact("raw anthropic-api-key-value raw").includes("anthropic-api-key-value"));
delete process.env.ANTHROPIC_API_KEY;

// short / empty tokens must not produce a degenerate matcher
for (const bad of ["", "   ", "short7"]) {
  const r = createRedactor(ConfigSchema.parse({ authToken: bad }));
  const text = "echo hi\nPATH=/usr/bin\nNODE_ENV=production";
  ok(`authToken ${JSON.stringify(bad)} leaves ordinary text untouched`, r.redact(text) === text);
}

// user patterns from config.redact are applied
{
  const r = createRedactor(ConfigSchema.parse({ redact: ["my-internal-[a-z0-9]{12}"] }));
  const out = r.redact("id my-internal-abc123def456 end");
  ok("config.redact pattern applied", !out.includes("my-internal-abc123def456") && out.includes("[redacted:"));
}

// redactEnabled: false is a pass-through
{
  const r = createRedactor(ConfigSchema.parse({ redactEnabled: false, authToken: "plain-literal-token", redact: ["my-internal-[a-z0-9]{12}"] }));
  const text = "sk-abcdefghijklmnopqrstuvwx plain-literal-token my-internal-abc123def456";
  ok("redactEnabled:false passes through", r.redact(text) === text);
  const ev = { kind: "log", t: 0, level: "info", message: text } as never;
  ok("redactEnabled:false redactEvent returns same ref", r.redactEvent(ev) === ev);
}

// builtins still active alongside literals
{
  const r = createRedactor(ConfigSchema.parse({ authToken: "plain-literal-token" }));
  ok("builtins still on", !r.redact("key sk-abcdefghijklmnopqrstuvwx").includes("sk-abcdefghijklmnopqrstuvwx"));
  const clean = "echo hi\nPATH=/usr/bin\nNODE_ENV=production";
  ok("no false positives", r.redact(clean) === clean);
}
